// (infer E)[] lê-se: "um array de qualquer coisa; chama E a essa coisa".
type ElementoDe<T> = T extends readonly (infer E)[] ? E : never;

type E1 = ElementoDe<number[]>; // number
type E2 = ElementoDe<(string | boolean)[]>; // string | boolean
const e1: E1 = 10;
const e2: E2 = true;

// Para arrays e tuplas, T[number] da Aula 01 faz o mesmo e lê-se melhor.
const cores = ["vermelho", "verde"] as const;
type Cor = (typeof cores)[number]; // "vermelho" | "verde"
const cor: Cor = "verde";

// Mas T[number] só funciona em tipos indexáveis por número.
// O padrão do infer pode ser qualquer forma, inclusive um genérico alheio.
type ConteudoDoConjunto<T> = T extends Set<infer E> ? E : never;
type E3 = ConteudoDoConjunto<Set<Date>>; // Date
const e3: E3 = new Date(2026, 0, 1);

// @ts-expect-error E1 é number, não string
const errado: E1 = "10";
console.log(e1, e2, cor, e3, errado);

// O padrão é uma assinatura de função; o infer fica no lugar do retorno.
type TipoDeRetorno<F> = F extends (...args: never[]) => infer R ? R : never;

// Aqui o infer fica no lugar da lista de parâmetros e devolve uma tupla.
type TiposDosParametros<F> = F extends (...args: infer P) => unknown ? P : never;

function criarArtigo(titulo: string, palavras: number) {
  return { titulo, palavras, publicado: false };
}

type Artigo = TipoDeRetorno<typeof criarArtigo>;
// { titulo: string; palavras: number; publicado: boolean }

type ArgsCriar = TiposDosParametros<typeof criarArtigo>;
// [titulo: string, palavras: number] — os nomes dos parâmetros sobrevivem

const artigo: Artigo = { titulo: "infer", palavras: 900, publicado: false };
const args: ArgsCriar = ["infer", 900];
const primeiro: ArgsCriar[0] = "outro título";

// @ts-expect-error o segundo parâmetro é number
const mau: ArgsCriar[1] = "novecentas";
console.log(artigo, args, primeiro, mau);

type ValorDaPromessa<T> = T extends Promise<infer V> ? V : T;

type V1 = ValorDaPromessa<Promise<string>>; // string
type V2 = ValorDaPromessa<number>; // number (não era promessa, passa intacto)
type V3 = ValorDaPromessa<Promise<Promise<boolean>>>; // Promise<boolean>

// A versão recursiva chama-se a si própria enquanto encontrar uma promessa.
type ValorFinal<T> = T extends Promise<infer V> ? ValorFinal<V> : T;
type V4 = ValorFinal<Promise<Promise<boolean>>>; // boolean

const v1: V1 = "pronto";
const v2: V2 = 7;
const v3: V3 = Promise.resolve(true);
const v4: V4 = true;

// @ts-expect-error V3 ainda é uma promessa: só foi retirada uma camada
const mau: V3 = true;
console.log(v1, v2, v3, v4, mau);

// Uma string ao nível dos tipos também é um padrão com buracos.
type Recurso<E extends string> = E extends `${infer R}:${string}` ? R : never;
type Accao<E extends string> = E extends `${string}:${infer A}` ? A : never;

type R1 = Recurso<"utilizador:criado">; // "utilizador"
type A1 = Accao<"utilizador:criado">; // "criado"
const r1: R1 = "utilizador";
const a1: A1 = "criado";

// Com recursão dá para percorrer uma rota inteira e recolher os parâmetros.
type ParametrosDaRota<S extends string> =
  S extends `${string}:${infer Nome}/${infer Resto}`
    ? Nome | ParametrosDaRota<`/${Resto}`>
    : S extends `${string}:${infer Nome}`
      ? Nome
      : never;

type ParamsArtigo = ParametrosDaRota<"/artigos/:id/comentarios/:comentarioId">;
// "id" | "comentarioId"
const p: ParamsArtigo = "comentarioId";

function construirUrl<S extends string>(
  rota: S,
  valores: { [K in ParametrosDaRota<S>]: string },
): string {
  return Object.entries(valores).reduce<string>(
    (url, [chave, valor]) => url.replace(`:${chave}`, String(valor)),
    rota,
  );
}

console.log(construirUrl("/artigos/:id", { id: "7" })); // "/artigos/7"

// @ts-expect-error falta o parâmetro comentarioId no objeto de valores
construirUrl("/artigos/:id/comentarios/:comentarioId", { id: "7" });
console.log(r1, a1, p);

// Dois infer com o mesmo nome em posição de RETORNO (covariante): união.
type RetornoComum<T> = T extends { a: () => infer R; b: () => infer R } ? R : never;
type U = RetornoComum<{ a: () => string; b: () => number }>; // string | number
const u1: U = "texto";
const u2: U = 42;
// @ts-expect-error U é a união string | number, não aceita boolean
const u3: U = true;

// Dois infer com o mesmo nome em posição de PARÂMETRO (contravariante): interseção.
type ParametroComum<T> = T extends { a: (x: infer P) => void; b: (x: infer P) => void }
  ? P
  : never;
type I = ParametroComum<{ a: (x: { nome: string }) => void; b: (x: { idade: number }) => void }>;
// { nome: string } & { idade: number }
const i1: I = { nome: "Ana", idade: 30 };
// @ts-expect-error a interseção exige as duas propriedades
const i2: I = { nome: "Ana" };

// infer X extends ... restringe o candidato e, com number, converte o literal.
type PrimeiroInteiro<S extends string> = S extends `${infer N extends number}${string}`
  ? N
  : never;
type N1 = PrimeiroInteiro<"7 dias">; // 7 (número, não "7")

type Porta<S extends string> = S extends `${string}:${infer P extends number}` ? P : never;
type N2 = Porta<"localhost:8080">; // 8080
const n1: N1 = 7;
const n2: N2 = 8080;
// @ts-expect-error o literal inferido é o número 8080, não a string
const n3: N2 = "8080";
console.log(u1, u2, u3, i1, i2, n1, n2, n3);

// Um alias pode referir-se a si próprio desde que haja um ramo que pare.
type ValorJson =
  | string
  | number
  | boolean
  | null
  | ValorJson[]
  | { [chave: string]: ValorJson };

const config: ValorJson = {
  nome: "loja",
  porta: 8080,
  ativo: true,
  etiquetas: ["beta", "interno"],
  base: { host: "localhost", replicas: null },
};

// @ts-expect-error uma função não é um valor JSON válido
const mau: ValorJson = { aoArrancar: () => 1 };

// O primeiro ramo trava a recursão nas funções; sem ele o mapped type
// destruiria a assinatura e deixaria um objeto vazio.
type ProfundamenteSoLeitura<T> = T extends (...args: never[]) => unknown
  ? T
  : T extends object
    ? { readonly [K in keyof T]: ProfundamenteSoLeitura<T[K]> }
    : T;

type ProfundamenteOpcional<T> = T extends (...args: never[]) => unknown
  ? T
  : T extends object
    ? { [K in keyof T]?: ProfundamenteOpcional<T[K]> }
    : T;

type Definicoes = {
  janela: { largura: number; titulo: string };
  atalhos: string[];
  aoFechar: () => void;
};

const base: Definicoes = {
  janela: { largura: 1024, titulo: "Loja" },
  atalhos: ["ctrl+s"],
  aoFechar: () => console.log("fechado"),
};

const fixas: ProfundamenteSoLeitura<Definicoes> = base;
// @ts-expect-error a propriedade aninhada passou a só de leitura
fixas.janela.largura = 800;
// @ts-expect-error o mapped type é homomórfico: o array virou readonly string[]
fixas.atalhos.push("ctrl+q");

const remendo: ProfundamenteOpcional<Definicoes> = { janela: { titulo: "Loja Beta" } };
console.log(config, mau, fixas.janela.titulo, remendo);

// Padrão clássico: cabeça e cauda, como numa lista ligada.
type Inverter<T extends readonly unknown[]> = T extends readonly [infer Cabeca, ...infer Resto]
  ? [...Inverter<Resto>, Cabeca]
  : [];
type I1 = Inverter<[1, 2, 3]>; // [3, 2, 1]
const i1: I1 = [3, 2, 1];

type Cauda<T extends readonly unknown[]> = T extends readonly [unknown, ...infer R] ? R : [];
type C1 = Cauda<[string, number, boolean]>; // [number, boolean]
const c1: C1 = [7, true];

// Recursão em cauda: o resultado parcial vai num acumulador e a chamada
// recursiva é a última coisa que o tipo faz. O compilador otimiza este caso.
type Juntar<
  T extends readonly string[],
  Sep extends string,
  Acc extends string = "",
> = T extends readonly [infer P extends string, ...infer R extends string[]]
  ? Juntar<R, Sep, Acc extends "" ? P : `${Acc}${Sep}${P}`>
  : Acc;

type J1 = Juntar<["artigos", ":id", "comentarios"], "/">; // "artigos/:id/comentarios"
const j1: J1 = "artigos/:id/comentarios";
// @ts-expect-error o literal produzido é exatamente "artigos/:id/comentarios"
const j2: J1 = "artigos/:id";

type Contar<N extends number, Acc extends unknown[] = []> = Acc["length"] extends N
  ? Acc
  : Contar<N, [...Acc, unknown]>;
const duzentos: Contar<200>["length"] = 200; // em cauda, 200 níveis passam

// @ts-expect-error TS2589: mesmo em cauda existe um tecto, perto dos mil níveis
type DemasiadoFundo = Contar<2000>;
console.log(i1, c1, j1, j2, duzentos);

