type ElementoDe<T> = T extends readonly (infer E)[] ? E : never;
type PrimeiroDe<T> = T extends readonly [infer P, ...unknown[]] ? P : never;

type A = ElementoDe<string[]>; // string
type B = ElementoDe<readonly [1, 2, 3]>; // 1 | 2 | 3
type C = PrimeiroDe<[boolean, string]>; // boolean
type D = ElementoDe<number>; // never (number não é um array)

const a: A = "olá";
const b: B = 2;
const c: C = false;
const d: D[] = [];

// @ts-expect-error B só admite os literais 1, 2 ou 3
const mau: B = 4;
console.log(a, b, c, d, mau);

type ValorFinal<T> = T extends Promise<infer V> ? ValorFinal<V> : T;
type RetornoResolvido<F> = F extends (...args: never[]) => infer R ? ValorFinal<R> : never;

async function obterArtigo(id: number) {
  return { id, titulo: "infer", palavras: 900 };
}

declare function obterEtiquetas(): Promise<Promise<string[]>>;

type Artigo = RetornoResolvido<typeof obterArtigo>;
// { id: number; titulo: string; palavras: number }
type Etiquetas = RetornoResolvido<typeof obterEtiquetas>; // string[]

const artigo: Artigo = { id: 1, titulo: "infer", palavras: 900 };
const etiquetas: Etiquetas = ["ts", "tipos"];

// @ts-expect-error Artigo já não é uma promessa
const mau: Artigo = Promise.resolve(artigo);
console.log(artigo, etiquetas, mau);

type Metodo<S extends string> = S extends `${infer M} ${string}` ? M : never;
type Caminho<S extends string> = S extends `${string} ${infer C}` ? C : never;
type ParametrosDaRota<S extends string> =
  S extends `${string}:${infer N}/${infer R}`
    ? N | ParametrosDaRota<`/${R}`>
    : S extends `${string}:${infer N}`
      ? N
      : never;

type Descricao<S extends string> = {
  metodo: Metodo<S>;
  caminho: Caminho<S>;
  parametros: ParametrosDaRota<S>[];
};

function descrever<S extends string>(entrada: S): Descricao<S> {
  const [metodo, caminho] = entrada.split(" ");
  const parametros = caminho
    .split("/")
    .filter((parte) => parte.startsWith(":"))
    .map((parte) => parte.slice(1));
  return { metodo, caminho, parametros } as Descricao<S>;
}

const d = descrever("GET /artigos/:id/comentarios/:comentarioId");
const metodo: "GET" = d.metodo;
const parametros: ("id" | "comentarioId")[] = d.parametros;

// @ts-expect-error o método inferido é o literal "GET"
const mau: "POST" = d.metodo;
console.log(metodo, d.caminho, parametros, mau);
// GET /artigos/:id/comentarios/:comentarioId [ 'id', 'comentarioId' ] GET

type Dividir<
  S extends string,
  Sep extends string,
  Acc extends string[] = [],
> = S extends `${infer Cabeca}${Sep}${infer Resto}`
  ? Dividir<Resto, Sep, [...Acc, Cabeca]>
  : [...Acc, S];

type Juntar<
  T extends readonly string[],
  Sep extends string,
  Acc extends string = "",
> = T extends readonly [infer P extends string, ...infer R extends string[]]
  ? Juntar<R, Sep, Acc extends "" ? P : `${Acc}${Sep}${P}`>
  : Acc;

type Partes = Dividir<"api.artigos.criado", ".">; // ["api", "artigos", "criado"]
const partes: Partes = ["api", "artigos", "criado"];

type Volta = Juntar<Partes, ".">; // "api.artigos.criado"
const volta: Volta = "api.artigos.criado";

// @ts-expect-error a tupla tem exatamente três elementos, nesta ordem
const mau: Partes = ["api", "artigos"];

function dividir<S extends string, Sep extends string>(
  texto: S,
  separador: Sep,
): Dividir<S, Sep> {
  return texto.split(separador) as Dividir<S, Sep>;
}

console.log(dividir("api.artigos.criado", ".")); // [ 'api', 'artigos', 'criado' ]
console.log(partes, volta, mau);
